import numpy as np
from rdkit import Chem
mol = Chem.MolFromXYZFile('opt1.xyz')
conf = mol.GetConformer()
N = mol.GetNumAtoms()
pos = {}
for i in range(N):
    p = conf.GetAtomPosition(i); pos[i] = np.array([p.x,p.y,p.z])
el = {i: mol.GetAtomWithIdx(i).GetSymbol() for i in range(N)}
# bond list (from molH pickle)
import pickle
molH = pickle.load(open('mol.pkl','rb'))
bonds = set()
for b in molH.GetBonds():
    i,j = b.GetBeginAtomIdx(), b.GetEndAtomIdx()
    bonds.add((min(i,j),max(i,j)))
# also 1-3 pairs to exclude
pairs13 = set()
for i in range(N):
    nbrs_i = [n.GetIdx() for n in molH.GetAtomWithIdx(i).GetNeighbors()]
    for a in nbrs_i:
        for c in [n.GetIdx() for n in molH.GetAtomWithIdx(a).GetNeighbors()]:
            if c!=i:
                pairs13.add((min(i,c),max(i,c)))
vdw = {'C':1.70,'H':1.20,'N':1.55,'O':1.52,'Ni':1.63}
minbad = []
for i in range(N):
    for j in range(i+1,N):
        if (i,j) in bonds or (i,j) in pairs13: continue
        dd = np.linalg.norm(pos[i]-pos[j])
        lim = vdw[el[i]]+vdw[el[j]]-0.45
        if dd < lim:
            minbad.append((i,j,el[i],el[j],dd))
print('close contacts (<vdw-0.45):', len(minbad))
for c in minbad[:20]: print('  ',c)
# dihedral of diene B=C-D=E
def dih(a,b,c,dd):
    b1=a-b; b2=c-b; b3=dd-c
    n1=np.cross(b1,b2); n2=np.cross(b2,b3)
    n1/=np.linalg.norm(n1); n2/=np.linalg.norm(n2)
    x=np.dot(n1,n2); y=np.dot(np.cross(n1,b2/np.linalg.norm(b2)),n2)
    return np.degrees(np.arctan2(y,x))
print('diene dihedral B=C-D=E (7-8-9-10):', dih(pos[7],pos[8],pos[9],pos[10]))
print('metallacycle dihedral Ni-B=C-C* (18-7-8-11):', dih(pos[18],pos[7],pos[8],pos[11]))
print('dihedral C*-C(8)-C(7)-A(6) i.e. 11-8-7-6:', dih(pos[11],pos[8],pos[7],pos[6]))
